import {useEffect,useMemo,useState} from 'react';
import type {ChangeEvent,FormEvent,ReactNode} from 'react';
import {ArrowLeft,ArrowRight,ArrowUpRight,Bell,CalendarDays,Clock,Crosshair,Dumbbell,ExternalLink,FileText,Gamepad2,Heart,HeartOff,Lightbulb,LoaderCircle,Music2,Plus,RefreshCw,Save,Search,SlidersHorizontal,Sparkles,Trash2,TrendingUp,Video,X} from 'lucide-react';
import type {Category,NewsEntry,Snapshot,Task,WorkspaceItem,WorkspaceKind} from './types';
import {RankStudioPage} from './ExtraPages';
import {YouTubeTrends} from './YoutubeTrends';
const nowDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const addDays=(s:string,n:number)=>{const d=new Date(s+'T12:00:00');d.setDate(d.getDate()+n);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
const readable=(s:string)=>s?new Date(s+'T12:00:00').toLocaleDateString('uk-UA',{day:'numeric',month:'short',year:'numeric'}):'Без дати';
const daysOfWeek=['Пн','Вт','Ср','Чт','Пт','Сб','Нд'];
const urgentTasks=(ts:Task[])=>ts.filter(t=>t.priority==='urgent'||t.priority==='critical'||t.priority==='high');
const sortedDayTasks=(ts:Task[])=>ts.slice().sort((a,b)=>({urgent:0,critical:1,high:2,normal:3,low:4}[a.priority||'normal']-({urgent:0,critical:1,high:2,normal:3,low:4}[b.priority||'normal']))||(a.time||'99:99').localeCompare(b.time||'99:99'));
const taskGroups=[{id:'critical',label:'Термінові / критичні',match:(t:Task)=>['urgent','critical'].includes(t.priority||'normal')},{id:'high',label:'Важливі',match:(t:Task)=>t.priority==='high'},{id:'everyday',label:'Повторювані',match:(t:Task)=>!['urgent','critical','high'].includes(t.priority||'normal')&&t.recurrence!=='none'},{id:'other',label:'Звичайні та інші',match:(t:Task)=>!['urgent','critical','high'].includes(t.priority||'normal')&&t.recurrence==='none'}];

const fieldText=(item:WorkspaceItem,key:string)=>String(item[key]??'');
const entryOccurs=(task:Task,d:string)=>{if(task.recurrence==='none')return task.dueDate===d;if(task.dueDate>d)return false;
 if(task.recurrence==='daily')return true;const date=new Date(d+'T12:00:00');if(task.recurrence==='weekdays')return ![0,6].includes(date.getDay());return Math.round((Date.parse(d+'T12:00:00Z')-Date.parse(task.dueDate+'T12:00:00Z'))/86400000)%7===0;};
const fields={
 projects:[{key:'title',label:'Назва проєкту',required:true},{key:'description',label:'Мета / опис',type:'textarea'},{key:'deadline',label:'Крайній дедлайн',type:'date'},{key:'steps',label:'Етапи (кожен з нового рядка)',type:'textarea'},{key:'note',label:'Ідеї / матеріали / посилання',type:'textarea'},{key:'progress',label:'Прогрес вручну (якщо без етапів), %',type:'number'},{key:'status',label:'Стан',type:'select',options:[['active','В роботі'],['paused','Пауза'],['done','Завершено']]}],
 gym:[{key:'title',label:'Домашнє тренування',required:true},{key:'date',label:'Дата',type:'date'},{key:'duration',label:'Тривалість, хв',type:'number'},{key:'exercises',label:'Вправи — підходи, повтори, ваги',type:'textarea'},{key:'note',label:'Самопочуття / нотатка',type:'textarea'}],
 cardio:[{key:'title',label:'Тренування',required:true},{key:'date',label:'Дата',type:'date'},{key:'duration',label:'Хвилини',type:'number'},{key:'distance',label:'Кілометри',type:'number'},{key:'speed',label:'Швидкість, км/год',type:'number'},{key:'incline',label:'Нахил, %',type:'number'},{key:'note',label:'Коментар',type:'textarea'}],
 cs2logs:[{key:'title',label:'Назва заняття',required:true},{key:'date',label:'Дата',type:'date'},{key:'duration',label:'Хвилини',type:'number'},{key:'dmKills',label:'DM — вбивства',type:'number'},{key:'botKills',label:'Боти — вбивства',type:'number'},{key:'matches',label:'Зіграні матчі',type:'number'},{key:'practice',label:'Aim / DM / демки / матчі',type:'textarea'},{key:'note',label:'Результат та помилки',type:'textarea'}],
 weight:[{key:'title',label:'Назва запису',required:true},{key:'date',label:'Дата',type:'date'},{key:'kg',label:'Вага, кг',type:'number'},{key:'waist',label:'Талія, см (необов’язково)',type:'number'},{key:'note',label:'Нотатки',type:'textarea'}],
 meals:[{key:'title',label:'Прийом їжі / страва',required:true},{key:'date',label:'Дата',type:'date'},{key:'calories',label:'Калорії (якщо відомо)',type:'number'},{key:'protein',label:'Білок, г (якщо відомо)',type:'number'},{key:'note',label:'Склад і порція',type:'textarea'}],
 channels:[{key:'title',label:'Назва каналу',required:true},{key:'url',label:'Посилання на канал',type:'url'},{key:'focus',label:'Тематика',type:'textarea'},{key:'uploadTime',label:'Типовий час публікації',type:'time'}],
 ideas:[{key:'title',label:'Назва ролика / ідеї',required:true},{key:'channelId',label:'Канал',type:'select',options:[]},{key:'date',label:'Дата публікації',type:'date'},{key:'status',label:'Етап',type:'select',options:[['idea','Ідея'],['script','Сценарій'],['editing','Монтаж'],['ready','Готове'],['published','Опубліковано']]},{key:'url',label:'Джерело / референс',type:'url'},{key:'note',label:'Сценарій / нотатки',type:'textarea'}],
 streams:[{key:'title',label:'Назва стріму',required:true},{key:'date',label:'Дата',type:'date'},{key:'time',label:'Початок',type:'time'},{key:'endTime',label:'Завершення',type:'time'},{key:'projectId',label:'Пов’язаний проєкт',type:'select',options:[]},{key:'status',label:'Стан',type:'select',options:[['planned','Заплановано'],['done','Проведено'],['cancelled','Скасовано']]},{key:'note',label:'Сценарій, ігри, завдання',type:'textarea'}],
 songs:[{key:'title',label:'Назва пісні',required:true},{key:'artist',label:'Виконавець'},{key:'url',label:'Посилання TikTok / інше',type:'url'},{key:'week',label:'П’ятниця для плейлиста',type:'date'},{key:'status',label:'Стан',type:'select',options:[['queued','У списку'],['added','Додано']]},{key:'note',label:'Звідки дізнався / нотатка',type:'textarea'}],
 programs:[{key:'title',label:'Назва програми',required:true},{key:'date',label:'Дата',type:'date'},{key:'focus',label:'Напрям',type:'select',options:[['general','Загальне'],['gym','Зал'],['cardio','Кардіо'],['nutrition','Харчування']]},{key:'content',label:'Повний план',type:'textarea'}]
} as const;
type Field={key:string;label:string;type?:string;required?:boolean;options?:readonly (readonly [string,string])[]};
const titleByKind:Record<WorkspaceKind,string>={projects:'Проєкт',gym:'Домашнє тренування',cardio:'Кардіо',cs2logs:'CS2-тренування',weight:'Замір',meals:'Харчування',channels:'YouTube-канал',ideas:'Ідея ролика',streams:'Стрім',songs:'Пісня',programs:'Програма'};
const defaultForKind=(kind:WorkspaceKind)=>({title:kind==='cardio'?'Ходьба на доріжці':kind==='weight'?'Контроль ваги':'',date:nowDate(),week:addDays(nowDate(),(5-new Date().getDay()+7)%7),status:kind==='projects'?'active':kind==='songs'?'queued':kind==='ideas'?'idea':'planned',progress:0});
export type WorkspaceActions={snapshot:Snapshot;refresh:()=>Promise<void>;report:(message:string)=>void;onAddTask:(date:string,category?:Category,title?:string)=>void;onEditTask?:(t:Task)=>void;onDeleteTask?:(t:Task)=>void};
function PageHeading({label,title,subtitle,action}:{label:string;title:string;subtitle:string;action?:ReactNode}){return <div className="hub-heading"><div><div className="hub-kicker">{label}</div><h1>{title}</h1><p>{subtitle}</p></div>{action}</div>;}
function Empty({icon,title,body}:{icon:ReactNode;title:string;body:string}){return <div className="hub-empty"><div className="hub-empty-icon">{icon}</div><strong>{title}</strong><p>{body}</p></div>;}
function CardRows({items,render}:{items:WorkspaceItem[];render:(i:WorkspaceItem)=>ReactNode}){return items.length?<div className="hub-records">{items.map(i=><div className="hub-record" key={i.id}>{render(i)}</div>)}</div>:null;}
function Editor({kind,item,initialDate,channels,projects,onClose,onSave}:{kind:WorkspaceKind;item?:WorkspaceItem|null;initialDate?:string;channels:WorkspaceItem[];projects:WorkspaceItem[];onClose:()=>void;onSave:(data:Record<string,unknown>)=>Promise<void>}){
 const [data,setData]=useState<Record<string,unknown>>(()=>item?{...item}:{...defaultForKind(kind),date:initialDate||nowDate()});const [busy,setBusy]=useState(false);const config=[...fields[kind]] as Field[];
 const submit=async(e:FormEvent)=>{e.preventDefault();setBusy(true);try{await onSave(data);onClose();}catch{/* UI reports the error and remains open */}finally{setBusy(false);}};
 return <div className="modal-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><div className="modal hub-editor"><div className="modal-head"><div><h2>{item?'Редагувати':'Додати'} · {titleByKind[kind]}</h2><p>Зберігається тільки на твоєму ПК</p></div><button className="icon-button" onClick={onClose}><X size={19}/></button></div><form onSubmit={e=>void submit(e)}>{config.map(f=>{const options=f.key==='channelId'?[['','Без каналу'],...channels.map(x=>[x.id,x.title])]:f.key==='projectId'?[['','Не пов’язано'],...projects.map(x=>[x.id,x.title])]:f.options||[];return <label className="hub-field" key={f.key}><span>{f.label}</span>{f.type==='textarea'?<textarea rows={f.key==='content'||f.key==='steps'?7:3} value={String(data[f.key]??'')} onChange={e=>setData({...data,[f.key]:e.target.value})} maxLength={10000}/>:f.type==='select'?<select value={String(data[f.key]??options[0]?.[0]??'')} onChange={e=>setData({...data,[f.key]:e.target.value})}>{options.map(([id,name])=><option value={id} key={id}>{name}</option>)}</select>:<input type={f.type==='number'?'number':f.type||'text'} min={f.type==='number'?0:f.type==='date'?'2000-01-01':undefined} max={f.type==='date'?'2100-12-31':f.key==='duration'?600:undefined} step={f.type==='number'?'any':undefined} required={f.required} maxLength={f.type==='number'?undefined:130} value={String(data[f.key]??'')} onChange={e=>setData({...data,[f.key]:e.target.value})}/>}</label>;})}<div className="modal-actions"><button type="button" className="button outline" onClick={onClose}>Скасувати</button><button type="submit" className="button primary" disabled={busy}><Save size={16}/> {busy?'Збереження…':'Зберегти'}</button></div></form></div></div>;
}
function useEditor({snapshot,refresh,report}:WorkspaceActions){const [editor,setEditor]=useState<{kind:WorkspaceKind;item?:WorkspaceItem|null;initialDate?:string}|null>(null);const [pendingDelete,setPendingDelete]=useState<{kind:WorkspaceKind;id:string;title:string}|null>(null);
 async function persist(data:Record<string,unknown>){if(!editor)return;try{if(editor.item)await window.lifehub.editWorkspace(editor.kind,editor.item.id,data);else await window.lifehub.addWorkspace(editor.kind,data);await refresh();report('Збережено');}catch(e){report(e instanceof Error?e.message:String(e));throw e;}}
 async function remove(kind:WorkspaceKind,id:string){const item=snapshot.workspace[kind].find(x=>x.id===id);setPendingDelete({kind,id,title:item?.title||'Запис'});}
 async function removeConfirmed(){if(!pendingDelete)return;try{await window.lifehub.deleteWorkspace(pendingDelete.kind,pendingDelete.id);await refresh();report('Видалено');}catch(e){report(String(e));}finally{setPendingDelete(null);}}
 const editorNode=<>{editor&&<Editor kind={editor.kind} item={editor.item} initialDate={editor.initialDate} channels={snapshot.workspace.channels} projects={snapshot.workspace.projects} onClose={()=>setEditor(null)} onSave={persist}/>}
 {pendingDelete&&<div className="modal-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)setPendingDelete(null);}}><div className="modal hub-confirm-modal"><h2>Видалити запис?</h2><p>{pendingDelete.title}</p><div className="modal-actions"><button className="button outline" onClick={()=>setPendingDelete(null)}>Скасувати</button><button className="button danger" onClick={()=>void removeConfirmed()}>Видалити</button></div></div></div>}</>;
 return {open:(kind:WorkspaceKind,item?:WorkspaceItem|null,initialDate?:string)=>setEditor({kind,item,initialDate}),remove,editorNode};}
function Actions({onEdit,onRemove}:{onEdit:()=>void;onRemove:()=>void}){return <div className="hub-inline-actions"><button onClick={onEdit} title="Редагувати"><FileText size={15}/></button><button onClick={onRemove} title="Видалити"><Trash2 size={15}/></button></div>;}

export function PlannerPage(props:WorkspaceActions & {categoryFilter?:Category;heading?:string}){const {snapshot,onAddTask,categoryFilter,heading,onEditTask,onDeleteTask}=props;const [focus,setFocus]=useState(nowDate());const [view,setView]=useState<'month'|'week'>('month');const [popupDate,setPopupDate]=useState<string|null>(null);const [armedDate,setArmedDate]=useState<string|null>(null);const [rightOpen,setRightOpen]=useState<Record<string,boolean>>({critical:true,high:true,everyday:true,other:true});const [detailsFilter,setDetailsFilter]=useState<'all'|'pending'>('all');useEffect(()=>{if(!popupDate)return;const fn=(e:KeyboardEvent)=>{if(e.key==='Escape')setPopupDate(null);};window.addEventListener('keydown',fn);return ()=>window.removeEventListener('keydown',fn);},[popupDate]);const [openGroups,setOpenGroups]=useState<Record<string,boolean>>({critical:true,high:true,everyday:false,other:false});const d=new Date(focus+'T12:00:00');const first=new Date(d.getFullYear(),d.getMonth(),1);const start=new Date(first);start.setDate(first.getDate()-(first.getDay()+6)%7);
 const cells=Array.from({length:42},(_,i)=>{const x=new Date(start);x.setDate(start.getDate()+i);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`;});const visible=view==='month'?cells:cells.filter(x=>{const ix=addDays(focus,-(new Date(focus+'T12:00:00').getDay()+6)%7);return x>=ix&&x<=addDays(ix,6);});
 const dayTasks=snapshot.tasks.filter(t=>(!categoryFilter||t.category===categoryFilter)&&entryOccurs(t,focus));const step=(n:number)=>{setArmedDate(null);if(view==='week')setFocus(addDays(focus,n*7));else {const nd=new Date(focus+'T12:00:00');nd.setMonth(nd.getMonth()+n);setFocus(`${nd.getFullYear()}-${String(nd.getMonth()+1).padStart(2,'0')}-${String(nd.getDate()).padStart(2,'0')}`);}};
 return <div className="hub-workspace hub-planner-v061"><PageHeading label="ORGANIZER / PLANNER" title={heading||'Плани'} subtitle="Спочатку обери дату, потім натисни на неї вдруге для повного плану. Усі зміни зберігаються локально." action={<button className="button primary" onClick={()=>onAddTask(focus,categoryFilter)}><Plus size={16}/> Додати подію</button>}/>
 <div className="hub-grid calendar-layout"><section className="hub-surface"><div className="hub-section-head"><div><h2>{new Date(focus+'T12:00:00').toLocaleDateString('uk-UA',{month:'long',year:'numeric'})}</h2><p>Число на даті — термінові та важливі справи. Натисни на день для всього плану.</p></div><div className="hub-tool-row"><button onClick={()=>{setFocus(nowDate());setArmedDate(null);}} className="hub-soft-button">Сьогодні</button><button className="hub-icon-button" onClick={()=>step(-1)}><ArrowLeft size={16}/></button><button className="hub-icon-button" onClick={()=>step(1)}><ArrowRight size={16}/></button><select className="hub-mini-select" value={view} onChange={e=>{setView(e.target.value as 'week'|'month');setArmedDate(null);}}><option value="month">Місяць</option><option value="week">Тиждень</option></select></div></div><div className="hub-calendar">{daysOfWeek.map(x=><div key={x} className="hub-weekday">{x}</div>)}{visible.map(x=>{const ts=snapshot.tasks.filter(t=>(!categoryFilter||t.category===categoryFilter)&&entryOccurs(t,x));return <button className={`hub-date ${x===focus?'is-selected':''} ${x.slice(0,7)!==focus.slice(0,7)?'is-outside':''} ${x===nowDate()?'is-today':''}`} key={x} onClick={()=>{if(armedDate===x){setPopupDate(x);setDetailsFilter('all');}else{setFocus(x);setArmedDate(x);}}} title={`Усього ${ts.length} справ, важливих ${urgentTasks(ts).length}. Відкрити ${readable(x)}`}><span className="hub-day-number">{+x.slice(8)}</span>{x===nowDate()&&<span className="hub-day-today-indicator" aria-label="Сьогодні"/>}{ts.length>0&&<small className="hub-day-subcount">{ts.length} справ</small>}{urgentTasks(ts).length>0&&<span className="hub-day-count hub-urgent-count" aria-label={`${urgentTasks(ts).length} важливих або критичних справ`}>{urgentTasks(ts).length}</span>}</button>;})}</div></section><section className="hub-surface hub-planner-right">
  <div className="hub-planner-right-hero"><span className="hub-kicker">ОБРАНИЙ ДЕНЬ</span><div className="hub-section-head"><div><h2>{readable(focus)}</h2><p>{dayTasks.length} справ · {dayTasks.filter(t=>t.completions.includes(focus)).length} виконано</p></div><button className="hub-icon-button" aria-label="Додати справу" onClick={()=>onAddTask(focus,categoryFilter)}><Plus size={18}/></button></div><button className="hub-planner-details-link" onClick={()=>{setPopupDate(focus);setDetailsFilter('all');}}>Повний план дня <ArrowUpRight size={15}/></button></div>
  <div className="hub-planner-right-groups">{taskGroups.map(group=>{const items=sortedDayTasks(dayTasks.filter(group.match));return <div className={'hub-side-group hub-side-'+group.id} key={group.id}><button className="hub-side-group-header" type="button" aria-expanded={Boolean(rightOpen[group.id])} onClick={()=>setRightOpen(v=>({...v,[group.id]:!v[group.id]}))}><span className="hub-side-mark"/><strong>{group.label}</strong><span className="hub-side-counter">{items.length}</span><span className="hub-side-chevron">{rightOpen[group.id]?'−':'+'}</span></button>{rightOpen[group.id]&&<div className="hub-side-group-body">{items.length?items.map(t=><div className={'hub-planner-item'+(t.completions.includes(focus)?' is-completed':'')} key={t.id}><div className="hub-planner-item-text"><strong>{t.title}</strong><small><Clock size={12}/> {t.allDay||!t.time?'Увесь день':t.time} · {t.recurrence==='none'?'Один раз':t.recurrence==='daily'?'Щодня':t.recurrence==='weekdays'?'Будні':'Щотижня'}</small>{t.note&&<p title={t.note}>{t.note}</p>}</div><div className="hub-planner-item-actions">{onEditTask&&<button type="button" aria-label={'Редагувати '+t.title} onClick={()=>onEditTask(t)}><FileText size={15}/></button>}{onDeleteTask&&<button type="button" aria-label={'Видалити '+t.title} onClick={()=>onDeleteTask(t)}><Trash2 size={15}/></button>}</div></div>):<p className="hub-side-empty">Немає справ у цій категорії</p>}</div>}</div>;})}</div>
  <div className="hub-planner-side-footer"><button type="button" className="hub-soft-button" onClick={()=>{setPopupDate(focus);setDetailsFilter('all');}}>Переглянути весь день <ArrowUpRight size={15}/></button></div>
 </section></div>{popupDate&&<div className="modal-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)setPopupDate(null);}}><div className="modal hub-date-popup hub-date-popup-pro" role="dialog" aria-modal="true" aria-label={'Справи на '+readable(popupDate)}><div className="hub-popup-hero"><div className="hub-popup-eyebrow"><CalendarDays size={16}/> ДЕТАЛІ ДНЯ</div><div className="hub-popup-hero-top"><div><h2>{new Date(popupDate+'T12:00:00').toLocaleDateString('uk-UA',{weekday:'long',day:'numeric',month:'long'})}</h2><p>Плани, дедлайни та повторювані звички</p></div><button className="hub-popup-x" onClick={()=>setPopupDate(null)} aria-label="Закрити"><X size={20}/></button></div><div className="hub-popup-metrics"><div><strong>{snapshot.tasks.filter(t=>(!categoryFilter||t.category===categoryFilter)&&entryOccurs(t,popupDate!)).length}</strong><span>Усього справ</span></div><div><strong>{snapshot.tasks.filter(t=>(!categoryFilter||t.category===categoryFilter)&&entryOccurs(t,popupDate!)&&urgentTasks([t]).length>0).length}</strong><span>Важливих</span></div><div><strong>{snapshot.tasks.filter(t=>(!categoryFilter||t.category===categoryFilter)&&entryOccurs(t,popupDate!)&&t.completions.includes(popupDate!)).length}</strong><span>Виконано</span></div></div></div><div className="hub-popup-toolbar"><div className="hub-popup-tabs"><button type="button" className={detailsFilter==='all'?'active':''} onClick={()=>setDetailsFilter('all')}>Усі</button><button type="button" className={detailsFilter==='pending'?'active':''} onClick={()=>setDetailsFilter('pending')}>Невиконані</button></div><div className="hub-popup-date-switch"><button type="button" aria-label="Попередній день" onClick={()=>{const d=addDays(popupDate,-1);setPopupDate(d);setFocus(d);setArmedDate(d);}}><ArrowLeft size={16}/></button><button type="button" aria-label="Наступний день" onClick={()=>{const d=addDays(popupDate,1);setPopupDate(d);setFocus(d);setArmedDate(d);}}><ArrowRight size={16}/></button></div></div>{taskGroups.map(group=>{const items=sortedDayTasks(snapshot.tasks.filter(t=>(!categoryFilter||t.category===categoryFilter)&&entryOccurs(t,popupDate!)&&group.match(t)&&(detailsFilter==='all'||!t.completions.includes(popupDate!))));return items.length?<section className={"hub-popup-group hub-popup-group-"+group.id} key={group.id}><button type="button" className="hub-accordion-title" aria-expanded={Boolean(openGroups[group.id])} onClick={()=>setOpenGroups(v=>({...v,[group.id]:!v[group.id]}))}><span>{group.label} <strong>{items.length}</strong></span><span>{openGroups[group.id]?"−":"+"}</span></button>{openGroups[group.id]&&items.map(t=><div className={"hub-popup-event"+(t.completions.includes(popupDate!)?" is-completed":"")} key={t.id}><div><strong>{t.title}</strong><small><Clock size={13}/> {t.time||'Увесь день'} · {t.recurrence==='daily'?'Щодня':t.recurrence==='weekdays'?'Будні':t.recurrence==='weekly'?'Щотижня':'Разова'} · {t.category}</small>{t.note&&<p>{t.note}</p>}</div>{onEditTask&&<button className="hub-icon-button" title="Редагувати справу" onClick={()=>{setPopupDate(null);onEditTask(t);}}><FileText size={16}/></button>}</div>)}</section>:null;})}{!snapshot.tasks.some(t=>(!categoryFilter||t.category===categoryFilter)&&entryOccurs(t,popupDate!))&&<p className="muted">На цю дату справ поки немає.</p>}<div className="modal-actions"><button className="button outline" onClick={()=>setPopupDate(null)}>Готово</button><button className="button primary" onClick={()=>{const date=popupDate||focus;setPopupDate(null);onAddTask(date,categoryFilter);}}><Plus size={16}/> Додати справу</button></div></div></div>}</div>;
}

export {ProjectsPage} from './ProjectStudio';

export function FitnessPage(props:WorkspaceActions & {kind:'fitness'|'cs2'}){const {snapshot,refresh,report,kind}=props;const edit=useEditor(props);const [tab,setTab]=useState<WorkspaceKind>(kind==='cs2'?'cs2logs':'gym');const [query,setQuery]=useState('');const [advice,setAdvice]=useState('');const [loading,setLoading]=useState(false);const [saveProfile,setSaveProfile]=useState(!snapshot.preferences.fitness.currentWeight||!snapshot.preferences.fitness.height);const [goal,setGoal]=useState(snapshot.preferences.fitness.goal);const [experience,setExperience]=useState(snapshot.preferences.fitness.experience);const [constraints,setConstraints]=useState(snapshot.preferences.fitness.constraints);const [weight,setWeight]=useState(String(snapshot.preferences.fitness.currentWeight||''));const [height,setHeight]=useState(String(snapshot.preferences.fitness.height||''));
 const [age,setAge]=useState(String(snapshot.preferences.fitness.age||''));const [activity,setActivity]=useState(snapshot.preferences.fitness.activity||'moderate');const [weeklyDays,setWeeklyDays]=useState(String(snapshot.preferences.fitness.weeklyDays||3));
 const [equipment,setEquipment]=useState(snapshot.preferences.fitness.homeEquipment||'Доріжка');
 const [cs2Goals,setCs2Goals]=useState(snapshot.preferences.cs2Targets);
 const [photoResult,setPhotoResult]=useState<{title:string;calories:number|null;protein:number|null;note:string;photoData:string}|null>(null);
 const [analyzingPhoto,setAnalyzingPhoto]=useState(false);
 useEffect(()=>{setTab(kind==='cs2'?'cs2logs':'gym');},[kind]);const logs=snapshot.workspace[tab]||[];const tabs:({id:WorkspaceKind;label:string})[]=kind==='fitness'?[{id:'gym',label:'Домашні тренування'},{id:'cardio',label:'Кардіо / доріжка'},{id:'meals',label:'Харчування'},{id:'weight',label:'Вага / заміри'},{id:'programs',label:'Програми'}]:[{id:'cs2logs',label:'CS2-журнал'}];
 async function profile(){try{await window.lifehub.setPreferences({fitness:{...snapshot.preferences.fitness,goal,experience,constraints,currentWeight:weight?Number(weight):null,height:height?Number(height):null,age:age?Number(age):null,activity,weeklyDays:Number(weeklyDays)||3,homeEquipment:equipment}});await refresh();report('Спортивний профіль збережено');setSaveProfile(false);}catch(e){report(String(e));}}
 async function askAI(){if(!query.trim()){report('Напиши запит до AI');return;}setLoading(true);try{const r=await window.lifehub.aiInsight(tab==='meals'?'nutrition':'fitness',query);setAdvice(r.text);await refresh();}catch(e){report(String(e));}finally{setLoading(false);}}
 async function analyzePhoto(){setAnalyzingPhoto(true);try{const result=await window.lifehub.analyzeFoodPhoto();if(result)setPhotoResult(result);await refresh();}catch(e){report(e instanceof Error?e.message:String(e));}finally{setAnalyzingPhoto(false);}}
 async function savePhotoMeal(){if(!photoResult)return;try{await window.lifehub.addWorkspace('meals',{title:photoResult.title,date:nowDate(),calories:photoResult.calories,protein:photoResult.protein,note:photoResult.note,photoData:photoResult.photoData});await refresh();setPhotoResult(null);report('Запис про харчування збережено');}catch(e){report(String(e));}}
 async function savePreset(title:string,content:string,focus:string){try{await window.lifehub.addWorkspace('programs',{title,date:nowDate(),focus,content});await refresh();setTab('programs');report('Шаблон додано до програм. Налаштуй його під свій стан.');}catch(e){report(String(e));}}
 async function saveCs2Targets(){try{await window.lifehub.setPreferences({cs2Targets:cs2Goals});await refresh();report('CS2-цілі збережено');}catch(e){report(String(e));}}
 const cs2Today=snapshot.workspace.cs2logs.filter(x=>x.date===nowDate());
 const cs2Sum=(key:string)=>cs2Today.reduce((sum,x)=>sum+(Number(x[key])||0),0);
 async function saveAdvice(){try{await window.lifehub.addWorkspace('programs',{title:tab==='meals'?'План харчування від AI':'Тренувальний план від AI',date:nowDate(),focus:tab==='meals'?'nutrition':tab==='cardio'?'cardio':'gym',content:advice});await refresh();report('AI-пропозицію збережено до «Програми»');setAdvice('');}catch(e){report(String(e));}}
 const recent=snapshot.workspace.weight.filter(x=>x.kg!==null).slice().sort((a,b)=>fieldText(a,'date').localeCompare(fieldText(b,'date'))).slice(-8);
 return <div className="hub-workspace"><PageHeading label={kind==='fitness'?'HEALTH / FITNESS':'PERFORMANCE / ESPORTS'} title={kind==='fitness'?'Фізична форма · вдома':'CS2 · Тренування'} subtitle={kind==='fitness'?'Домашні вправи, доріжка, харчування й заміри — у твоєму темпі.':'Відстежуй DM, ботів, матчі та тривалість занять без обов’язкового AI.'} action={<button className="button primary" onClick={()=>edit.open(tab)}><Plus size={16}/> Новий запис</button>}/>
 <div className="hub-tabs">{tabs.map(t=><button key={t.id} onClick={()=>setTab(t.id)} className={tab===t.id?'active':''}>{t.label}</button>)}</div>
 {kind==='fitness'&&<section className="hub-surface hub-profile"><div className="hub-section-head"><div><h2>Спочатку — твої параметри</h2><p>Внеси дані один раз; потім їх можна буде редагувати. Дані зберігаються локально; AI бачить їх тільки під час твого запиту.</p></div><button className="hub-soft-button" onClick={()=>setSaveProfile(!saveProfile)}><SlidersHorizontal size={15}/> {saveProfile?'Згорнути':'Редагувати параметри'}</button></div>{saveProfile?<div className="hub-profile-form"><label>Ціль<select value={goal} onChange={e=>setGoal(e.target.value)}><option value="general">Загальна форма</option><option value="loss">Зниження ваги</option><option value="muscle">Набір м’язів</option><option value="endurance">Витривалість</option></select></label><label>Досвід<select value={experience} onChange={e=>setExperience(e.target.value)}><option value="beginner">Початківець</option><option value="intermediate">Середній</option><option value="advanced">Досвідчений</option></select></label><label>Вік (за бажанням)<input type="number" min="1" max="110" value={age} onChange={e=>setAge(e.target.value)}/></label><label>Рівень щоденної активності<select value={activity} onChange={e=>setActivity(e.target.value)}><option value="low">Малорухливий</option><option value="moderate">Помірний</option><option value="high">Активний</option></select></label><label>Днів на тиждень<input type="number" min="1" max="7" value={weeklyDays} onChange={e=>setWeeklyDays(e.target.value)}/></label><label>Обладнання вдома<input value={equipment} onChange={e=>setEquipment(e.target.value)} maxLength={200}/></label><label>Вага (кг)<input type="number" step="0.1" value={weight} onChange={e=>setWeight(e.target.value)}/></label><label>Зріст (см)<input type="number" value={height} onChange={e=>setHeight(e.target.value)}/></label><label className="wide">Обмеження / травми / доступне обладнання<textarea value={constraints} onChange={e=>setConstraints(e.target.value)} rows={3}/></label><button className="button primary" onClick={()=>void profile()}><Save size={16}/> Зберегти профіль</button></div>:<div className="hub-profile-summary"><span>Ціль: <strong>{{general:'Форма',loss:'Схуднення',muscle:'М’язи',endurance:'Витривалість'}[snapshot.preferences.fitness.goal]||'Загальна'}</strong></span><span>Остання записана вага: <strong>{recent.at(-1)?.kg?`${recent.at(-1)?.kg} кг`:'—'}</strong></span><span>Тренувань: <strong>{snapshot.workspace.gym.length+snapshot.workspace.cardio.length}</strong></span></div>}</section>}
 {kind==='fitness'&&<section className="hub-surface hub-presets"><div className="hub-section-head"><div><h2>Програми для дому без API</h2><p>Приклади для адаптації під свої можливості — не медичні призначення.</p></div></div><div className="hub-preset-grid"><button className="hub-soft-button" onClick={()=>void savePreset('Стартова домашня програма', '3 рази на тиждень за самопочуттям: 5 хв легкої розминки, 2×8 присідань до стільця, 2×8 віджимань від стіни, 2×10 сідничного мосту, 5 хв розтяжки. Збільшувати поступово, якщо комфортно.', 'general')}>+ Стартові вправи</button><button className="hub-soft-button" onClick={()=>void savePreset('Доріжка — легкий темп', 'Почни із 15–20 хв легкої ходьби на доріжці 3–4 рази на тиждень. Поступово змінюй тривалість лише за комфортного самопочуття. Не прив’язуй до спалення їжі.', 'cardio')}>+ Доріжка · старт</button><button className="hub-soft-button" onClick={()=>void savePreset('Основа харчування', 'Регулярні прийоми їжі, білок і овочі за можливості, достатньо питної води; різноманітність та зручні порції. Калорійність індивідуальна, не визначати дефіцит без даних.', 'nutrition')}>+ Основи харчування</button></div></section>}
 {kind==='cs2'&&<section className="hub-surface hub-cs2-goals"><div className="hub-section-head"><div><h2>Мої цілі на сьогодні</h2><p>Прогрес рахується із записів CS2-журналу за поточну дату.</p></div></div><div className="hub-cs2-goal-grid">{([{key:'dmKills',label:'DM-фраги'},{key:'botKills',label:'Боти'},{key:'matches',label:'Матчі'},{key:'minutes',label:'Хвилини'}] as const).map(g=>{const amount=g.key==='minutes'?cs2Sum('duration'):cs2Sum(g.key),target=cs2Goals[g.key]||1;return <div className="hub-cs2-goal" key={g.key}><label>{g.label}<input type="number" min="1" value={cs2Goals[g.key]} onChange={e=>setCs2Goals(old=>({...old,[g.key]:Number(e.target.value)||0}))}/></label><strong>{amount} / {target}</strong><div className="task-meter-track"><span style={{width:`${Math.min(100,amount/target*100)}%`}}/></div></div>})}</div><button className="button outline" onClick={()=>void saveCs2Targets()}><Save size={15}/> Зберегти цілі</button><p className="hub-footnote">Можна вести 500 фрагів DM, 1000 ботів, 5 матчів — редагуй цілі. Аналіз .dem — окрема майбутня інтеграція; сама нейромережа не читає демку без спеціального парсера.</p></section>}
 {kind==='fitness'&&tab==='meals'&&<section className="hub-surface hub-food-photo"><div className="hub-section-head"><div><h2>Фото страви → оцінка AI</h2><p>Вибери фото з ПК. Перед збереженням перевір назву, порцію та приблизну калорійність.</p></div><button className="button primary" disabled={!snapshot.hasKey||analyzingPhoto} onClick={()=>void analyzePhoto()}><Plus size={15}/> {analyzingPhoto?'Аналіз…':'Аналізувати фото'}</button></div>{!snapshot.hasKey&&<p className="hub-notice">Потрібен API-ключ. Звичайний журнал їжі безкоштовний.</p>}{photoResult&&<div className="hub-photo-result"><img src={photoResult.photoData} alt="Обрана страва"/><div><label className="hub-field"><span>Назва страви</span><input value={photoResult.title} onChange={e=>setPhotoResult(old=>old?{...old,title:e.target.value}:old)}/></label><div className="hub-photo-values"><label className="hub-field"><span>Калорії (оцінка)</span><input type="number" min="0" value={photoResult.calories??''} onChange={e=>setPhotoResult(old=>old?{...old,calories:e.target.value?Number(e.target.value):null}:old)}/></label><label className="hub-field"><span>Білок, г (оцінка)</span><input type="number" min="0" value={photoResult.protein??''} onChange={e=>setPhotoResult(old=>old?{...old,protein:e.target.value?Number(e.target.value):null}:old)}/></label></div><label className="hub-field"><span>Примітка / порція</span><textarea rows={2} value={photoResult.note} onChange={e=>setPhotoResult(old=>old?{...old,note:e.target.value}:old)}/></label><div className="hub-tool-row"><button className="button primary" onClick={()=>void savePhotoMeal()}>Додати в журнал</button><button className="button outline" onClick={()=>setPhotoResult(null)}>Відхилити</button></div></div></div>}<small>Оцінка лише за фото може суттєво помилятися. Остаточний запис робиш ти.</small></section>}
 <div className="hub-grid hub-training-layout"><section className="hub-surface"><div className="hub-section-head"><div><h2>{tabs.find(x=>x.id===tab)?.label}</h2><p>{logs.length} записів · ручний журнал</p></div><button className="hub-icon-button" onClick={()=>edit.open(tab)}><Plus size={17}/></button></div><CardRows items={logs} render={x=><>{Boolean(x.photoData)&&<img className="hub-meal-thumb" src={fieldText(x,'photoData')} alt="Фото страви"/>}<div className="hub-record-body"><strong>{x.title}</strong><div className="hub-meta">{readable(fieldText(x,'date'))}{x.duration?` · ${x.duration} хв`:''}{x.kg?` · ${fieldText(x,'kg')} кг`:''}{x.distance?` · ${x.distance} км`:''}{x.calories?` · ${x.calories} ккал`:''}</div>{['exercises','practice','note','content'].map(k=>x[k]?<p key={k} className="hub-record-detail">{fieldText(x,k)}</p>:null)}</div><Actions onEdit={()=>edit.open(tab,x)} onRemove={()=>void edit.remove(tab,x.id)}/></>}/>{!logs.length&&<Empty icon={kind==='fitness'?<Dumbbell size={26}/>:<Crosshair size={26}/>} title="Тут поки порожньо" body="Запиши перше тренування або створіть новий план із AI."/>}</section>
 <section className="hub-surface hub-ai-side"><div className="hub-ai-symbol"><Sparkles size={20}/></div><h2>AI-тренер</h2><p>Попроси програму скласти тижневу програму, урізноманітнити доріжку або допомогти з харчуванням. Вона пропонує — ти вирішуєш.</p><textarea rows={4} placeholder={tab==='meals'?'Склади збалансований приклад харчування на тиждень...':kind==='cs2'?'Допоможи підсумувати мою статистику CS2 за останні дні...' :'План вправ вдома без спортзалу та ходьби на моїй доріжці...' } value={query} onChange={e=>setQuery(e.target.value)}/><button className="button primary wide" disabled={loading||!snapshot.hasKey} onClick={()=>void askAI()}>{loading?<LoaderCircle size={16}/>:<Sparkles size={16}/>} {loading?'Готуємо рекомендацію…':'Запропонувати план'}</button>{!snapshot.hasKey&&<p className="hub-notice">Спочатку підключи OpenAI API в налаштуваннях.</p>}{advice&&<div className="hub-ai-result"><pre>{advice}</pre><button className="button outline" onClick={()=>void saveAdvice()}><Save size={15}/> Зберегти після перевірки</button></div>}<small className="hub-health-note">Це інструмент планування, а не медична консультація. Не використовуй рекомендації для екстремальних дієт чи навантажень.</small></section></div>
 {kind==='fitness'&&recent.length>1&&<section className="hub-surface"><h2>Історія ваги</h2><div className="hub-weight-chart">{recent.map(x=><div key={x.id}><strong>{fieldText(x,'kg')} кг</strong><div className="hub-weight-bar" style={{height:`${Math.max(25,Number(x.kg||0)/Math.max(...recent.map(z=>Number(z.kg)||1))*130)}px`}}/><small>{readable(fieldText(x,'date'))}</small></div>)}</div></section>}{edit.editorNode}</div>;
}

function InsightPanel({kind,snapshot,refresh,report,defaultQuery}:{kind:'trends'|'youtube'|'streams';snapshot:Snapshot;refresh:()=>Promise<void>;report:(s:string)=>void;defaultQuery:string}){const [query,setQuery]=useState(defaultQuery),[answer,setAnswer]=useState(''),[working,setWorking]=useState(false);
 async function run(){setWorking(true);try{const r=await window.lifehub.aiInsight(kind,query);setAnswer(r.text);await refresh();}catch(e){report(String(e));}finally{setWorking(false);}}
 return <section className="hub-surface hub-insight"><div className="hub-section-head"><div><h2><Sparkles size={17}/> AI-аналітика</h2><p>Пропозиції для розгляду, не автоматичні рішення</p></div><span className="hub-chip">API за запитом</span></div><textarea rows={2} value={query} onChange={e=>setQuery(e.target.value)}/><button className="button primary" disabled={working||!snapshot.hasKey} onClick={()=>void run()}>{working?'Аналізую…':'Отримати AI-ідеї'} <ArrowUpRight size={16}/></button>{!snapshot.hasKey&&<p className="hub-notice">Потрібен API-ключ. Безкоштовні функції працюють без нього.</p>}{answer&&<div className="hub-ai-result"><pre>{answer}</pre></div>}</section>;
}

export function YoutubePage(props:WorkspaceActions){const {snapshot,refresh,report,onAddTask}=props,edit=useEditor(props);const [tab,setTab]=useState<'channels'|'ideas'|'studio'|'radar'>('channels');const channels=snapshot.workspace.channels,ideas=snapshot.workspace.ideas;const radar=snapshot.news.items.filter(x=>['internet','games','tech'].includes(x.category)).slice(0,7);
 return <div className="hub-workspace"><PageHeading label="CREATOR / YOUTUBE" title="YouTube Studio" subtitle="Всі канали, контент-плани, ідеї, публікації та тренди в одному робочому просторі." action={<button className="button primary" onClick={()=>edit.open(tab==='channels'?'channels':'ideas')}><Plus size={16}/> {tab==='channels'?'Додати канал':'Нова ідея'}</button>}/><div className="hub-tabs">{[['channels','Мої канали'],['ideas','Контент-план'],['studio','Відео Inbox'],['radar','Trend Radar']].map(([id,title])=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id as typeof tab)}>{title}</button>)}</div>
 {tab==='channels'&&<div className="hub-project-grid">{channels.map(c=><section className="hub-surface" key={c.id}><div className="hub-section-head"><div className="hub-channel-icon"><Video size={19}/></div><Actions onEdit={()=>edit.open('channels',c)} onRemove={()=>void edit.remove('channels',c.id)}/></div><h2>{c.title}</h2><p>{fieldText(c,'focus')||'Тематику ще не вказано'}</p><div className="hub-meta"><Clock size={14}/> {c.uploadTime?`Публікації: ${c.uploadTime}`:'Час публікацій не вказано'}</div><div className="hub-tool-row">{Boolean(c.url)&&<button className="hub-soft-button" onClick={()=>void window.lifehub.openLink(fieldText(c,'url')).catch(e=>report(String(e)))}><ExternalLink size={15}/> Відкрити канал</button>}<button className="hub-soft-button" onClick={()=>{setTab('ideas');edit.open('ideas');}}><Plus size={14}/> Ролик</button></div></section>)}{!channels.length&&<section className="hub-surface"><Empty icon={<Video size={27}/>} title="Додай свій канал" body="Почни з Rank It і підключай інші канали в будь-який час."/></section>}<section className="hub-surface hub-integration"><h2>Статистика YouTube</h2><p>Справжні перегляди, CTR, утримання аудиторії та завантаження відео потребують офіційного Google OAuth і YouTube Data/Analytics API. Зараз нічого не вигадуємо.</p><span className="hub-chip">Інтеграція попереду</span><div className="hub-integration-guide"><strong>Як безпечно під’єднаємо канал</strong><p>1. Створимо Google Cloud проєкт → YouTube Data API v3 та YouTube Analytics API. 2. Налаштуємо OAuth Desktop. 3. У LifeHub з’явиться кнопка «Увійти з Google» з дозволами на статистику або публікацію. Пароль і OAuth-токени нікому в чат не надсилай.</p><button className="hub-soft-button" onClick={()=>void window.lifehub.openLink('https://console.cloud.google.com/').catch(e=>report(String(e)))}>Google Cloud <ExternalLink size={14}/></button></div></section></div>}
 {tab==='ideas'&&<section className="hub-surface"><div className="hub-section-head"><div><h2>Контент-план</h2><p>Ідея → сценарій → монтаж → готове → публікація</p></div><button className="hub-soft-button" onClick={()=>edit.open('ideas')}><Plus size={15}/> Додати</button></div><CardRows items={ideas} render={i=><><div className="hub-record-body"><strong>{i.title}</strong><div className="hub-meta">{channels.find(x=>x.id===i.channelId)?.title||'Без каналу'} · {i.date?readable(fieldText(i,'date')):'Без дати'} · {fieldText(i,'status')}</div>{Boolean(i.note)&&<p className="hub-record-detail">{fieldText(i,'note')}</p>}<div className="hub-tool-row">{Boolean(i.url)&&<button className="hub-soft-button" onClick={()=>void window.lifehub.openLink(fieldText(i,'url'))}>Джерело <ExternalLink size={13}/></button>}<button className="hub-soft-button" onClick={()=>onAddTask(fieldText(i,'date')||nowDate(),'rankdaily',`Підготувати: ${i.title}`)}>У план <CalendarDays size={14}/></button></div></div><Actions onEdit={()=>edit.open('ideas',i)} onRemove={()=>void edit.remove('ideas',i.id)}/></>}/>{!ideas.length&&<Empty icon={<Lightbulb size={26}/>} title="Поки без ідей" body="Додай задум для нового Shorts або переглянь Trend Radar."/>}</section>}
 {tab==='studio'&&<RankStudioPage report={report}/>}
 {tab==='radar'&&<><YouTubeTrends snapshot={snapshot} report={report} onAdd={title=>onAddTask(nowDate(),'rankdaily',title)}/><section className="hub-surface"><div className="hub-section-head"><div><h2>Теми з новинних джерел</h2><p>Потенційні ідеї, не підтверджена статистика переглядів YouTube.</p></div><span className="hub-chip">RSS</span></div>{radar.map(x=><div className="hub-radar-row" key={x.id}><div><strong>{x.title}</strong><small>{x.source} · {new Date(x.publishedAt).toLocaleDateString('uk-UA')}</small></div><div className="hub-tool-row"><button className="hub-soft-button" title="Оригінальна стаття, не відео" onClick={()=>void window.lifehub.openLink(x.url).catch(e=>report(String(e)))}>Стаття <ExternalLink size={13}/></button><button className="hub-soft-button" onClick={()=>onAddTask(nowDate(),'rankdaily',`Оцінити тему: ${x.title.slice(0,72)}`)}><Plus size={15}/> У план</button></div></div>)}{!radar.length&&<Empty icon={<TrendingUp size={26}/>} title="Джерела ще не оновлені" body="Зайди в «Новини» й натисни «Оновити», щоб отримати свіжі теми."/>}</section><InsightPanel snapshot={snapshot} refresh={refresh} report={report} kind="trends" defaultQuery="Вибери 5 перспективних тем із доступних заголовків, запропонуй короткі ідеї YouTube Shorts і поясни чому. Без вигаданих переглядів."/></>}{edit.editorNode}</div>;
}

export function StreamsPage(props:WorkspaceActions){const {snapshot,refresh,report,onAddTask}=props,edit=useEditor(props);const items=snapshot.workspace.streams;const [focus,setFocus]=useState(nowDate());const shift=(n:number)=>setFocus(addDays(focus,n*7));const week=Array.from({length:7},(_,i)=>addDays(focus,i-(new Date(focus+'T12:00:00').getDay()+6)%7));
 return <div className="hub-workspace"><PageHeading label="CREATOR / LIVE" title="Стрімерство" subtitle="Плани ефірів, теми, підготовка, сценарії й зв’язок із проєктами." action={<button className="button primary" onClick={()=>edit.open('streams')}><Plus size={16}/> Запланувати стрім</button>}/><section className="hub-surface hub-stream-calendar"><div className="hub-section-head"><div><h2>Тиждень ефірів</h2><p>Обери дату, щоби спланувати стрім.</p></div><div className="hub-tool-row"><button className="hub-icon-button" onClick={()=>shift(-1)}><ArrowLeft size={16}/></button><button className="hub-soft-button" onClick={()=>setFocus(nowDate())}>Сьогодні</button><button className="hub-icon-button" onClick={()=>shift(1)}><ArrowRight size={16}/></button></div></div><div className="hub-stream-week">{week.map(date=><button className={focus===date?'is-selected':''} onClick={()=>setFocus(date)} key={date}><strong>{date.slice(8)}</strong><span>{new Date(date+'T12:00:00').toLocaleDateString('uk-UA',{weekday:'short'})}</span><small>{items.filter(x=>x.date===date).length} ефірів</small></button>)}</div><div className="hub-day-tasks">{items.filter(x=>x.date===focus).map(x=><div key={x.id} className="hub-day-task"><strong>{x.title}</strong><small>{fieldText(x,'time')||'Час не вказаний'} — {fieldText(x,'endTime')||'кінець не вказаний'}</small></div>)}</div><button className="button outline" onClick={()=>edit.open('streams',null,focus)}><Plus size={15}/> Додати ефір на {readable(focus)}</button></section><div className="hub-grid hub-training-layout"><section className="hub-surface"><div className="hub-section-head"><div><h2>Календар ефірів</h2><p>{items.length} запланованих/минулых записів</p></div></div><CardRows items={items} render={s=><><div className="hub-record-body"><strong>{s.title}</strong><div className="hub-meta"><CalendarDays size={13}/>{readable(fieldText(s,'date'))} {fieldText(s,'time')}{Boolean(s.endTime)?'–'+fieldText(s,'endTime'):''} · {fieldText(s,'status')} {snapshot.workspace.projects.find(x=>x.id===s.projectId)?` · ${snapshot.workspace.projects.find(x=>x.id===s.projectId)?.title}`:''}</div>{Boolean(s.note)&&<p className="hub-record-detail">{fieldText(s,'note')}</p>}<button className="hub-soft-button" onClick={()=>onAddTask(fieldText(s,'date')||nowDate(),'twitch',`Підготовка до стріму: ${s.title}`)}>У план дня <CalendarDays size={13}/></button></div><Actions onEdit={()=>edit.open('streams',s)} onRemove={()=>void edit.remove('streams',s.id)}/></>}/>{!items.length&&<Empty icon={<Gamepad2 size={26}/>} title="Стрімів ще немає" body="Додай перший ефір, час і теми. Проєкти можна прив’язувати до стрімів."/>}</section><InsightPanel snapshot={snapshot} refresh={refresh} report={report} kind="streams" defaultQuery="Запропонуй три теми для стрімів і конкретний чекліст підготовки."/></div>{edit.editorNode}</div>;
}

const newsCat:Record<string,string>={anime:'Аніме',games:'Ігри',internet:'Інтернет',world:'Світ',tech:'Технології',europe:'Європа',america:'Америка',asia:'Азія',africa:'Африка',cis:'СНД / регіон'};
const newsTokens=(title:string)=>new Set((title.toLowerCase().match(/[\p{L}]{4,}/gu)||[]).filter(w=>!['news','today','latest','about','after','with','from','this','that','have','your','will','коли','після','сьогодні','новини','новий','стало','який','якщо','with','live'].includes(w)).slice(0,20));
const newsArt:Record<string,ReactNode>={anime:<Sparkles size={34}/>,games:<Gamepad2 size={34}/>,tech:<Sparkles size={34}/>,internet:<TrendingUp size={34}/>,world:<ExternalLink size={34}/>,europe:<ExternalLink size={34}/>,america:<ExternalLink size={34}/>,asia:<ExternalLink size={34}/>,africa:<ExternalLink size={34}/>,cis:<ExternalLink size={34}/>};
function NewsVisual({article}:{article:NewsEntry}){
 const [broken,setBroken]=useState(false);
 if(article.imageUrl&&!broken)return <figure className="hub-news-figure"><img className="hub-news-image" src={article.imageUrl} alt={article.imageCaption||"Фото з новинного джерела"} loading="lazy" referrerPolicy="no-referrer" title={article.imageCaption||"Фото з джерела"} onError={()=>setBroken(true)}/>{article.imageCaption?.startsWith('AI-ілюстрація')&&<figcaption className="hub-ai-image-label">AI-ілюстрація — не фотографія події</figcaption>}{article.imageCreditUrl&&<figcaption><button onClick={()=>void window.lifehub.openLink(article.imageCreditUrl!).catch(()=>{})}>{article.imageCaption||'Ілюстрація з Wikipedia'}</button></figcaption>}</figure>;
 const logoDomains:Record<string,string>={'Anime News Network':'animenewsnetwork.com','BBC News':'bbc.com','Reuters':'reuters.com','Al Jazeera':'aljazeera.com','Comic Book Resources':'cbr.com','Mashable':'mashable.com','TechRepublic':'techrepublic.com','IGN':'ign.com','The Verge':'theverge.com','AP News':'apnews.com','Billboard':'billboard.com'};
 const sourceDomain=Object.entries(logoDomains).find(([name])=>article.source.toLowerCase().includes(name.toLowerCase()))?.[1];
 return <div className={`hub-news-placeholder is-${article.category}`} title="Оригінальне фото статті недоступне">{sourceDomain?<><img className="hub-news-source-logo" src={`https://www.google.com/s2/favicons?domain=${sourceDomain}&sz=128`} alt={`Логотип джерела ${article.source}`} loading="lazy"/><span>Джерело: {article.source}</span></>:<>{newsArt[article.category]||<TrendingUp size={34}/>}<span>{newsCat[article.category]||'Новини'}</span></>}</div>;
}
export function NewsPage(props:WorkspaceActions){
 const {snapshot,refresh,report,onAddTask}=props;
 const [tab,setTab]=useState('all'),[sort,setSort]=useState<'forYou'|'recent'>('forYou');
 const [busy,setBusy]=useState(false),[visibleCount,setVisibleCount]=useState(30);
 const [translations,setTranslations]=useState<Record<string,string>>({}),[translating,setTranslating]=useState('');
 const [hiddenNow,setHiddenNow]=useState<Set<string>>(()=>new Set());
 const [imageConfirm,setImageConfirm]=useState<string|null>(null),[generating,setGenerating]=useState('');
 const reactions=snapshot.newsFeedback;
 async function load(){setBusy(true);try{const n=await window.lifehub.refreshNews();await refresh();report(n.items.length?`Оновлено: ${n.items.length} статей`:'RSS недоступний. Перевір інтернет.');}catch(e){report(e instanceof Error?e.message:String(e));}finally{setBusy(false);}}
 async function translate(article:NewsEntry,language:'uk'|'ru'){setTranslating(article.id);try{const r=await window.lifehub.aiInsight('translate',`Мова перекладу: ${language==='ru'?'російська':'українська'}. Текст: ${article.title}`);setTranslations(old=>({...old,[article.id]:r.text}));await refresh();}catch(e){report(String(e));}finally{setTranslating('');}}
 async function act(id:string,kind:'interesting'|'not'|'save'){
  setHiddenNow(prev=>new Set(prev).add(id));
  try{if(kind==='save')await window.lifehub.saveNews(id);else await window.lifehub.rateNews(id,kind);await refresh();}
  catch(e){setHiddenNow(prev=>{const next=new Set(prev);next.delete(id);return next;});report(String(e));}
 }
 async function unsave(id:string){try{await window.lifehub.unsaveNews(id);await refresh();report('Видалено зі збереженого');}catch(e){report(String(e));}}
 async function illustrate(id:string){setGenerating(id);try{await window.lifehub.illustrateNews(id);await refresh();report('AI-ілюстрацію створено та збережено на ПК');}catch(e){report(e instanceof Error?e.message:String(e));}finally{setGenerating('');setImageConfirm(null);}}
 const sorted=useMemo(()=>{
  if(tab==='saved')return snapshot.newsSaved;
  const arr=snapshot.news.items.filter(x=>!hiddenNow.has(x.id)&&(tab==='all'||x.category===tab));
  if(sort==='recent')return arr.slice().sort((a,b)=>b.publishedAt.localeCompare(a.publishedAt));
  const scores:Record<string,number>={},likes:Map<string,number>=new Map();
  for(const f of Object.values(reactions)){if(f.vote!=='interesting')continue;scores[f.category]=(scores[f.category]||0)+1;
   if(f.title)for(const word of newsTokens(f.title))likes.set(word,(likes.get(word)||0)+1);}
  const score=(x:NewsEntry)=>{let topic=0;for(const word of newsTokens(x.title))topic+=Math.min(3,likes.get(word)||0);
   const days=Math.max(0,(Date.now()-Date.parse(x.publishedAt))/86400000);return Math.min(scores[x.category]||0,5)*.5+Math.min(topic,10)*.3-Math.min(days,7)*.22+(x.imageUrl ? 0.15 : 0);};
  return arr.slice().sort((a,b)=>score(b)-score(a));
 },[snapshot.news.items,snapshot.newsSaved,reactions,tab,sort,hiddenNow]);
 const changeTab=(id:string)=>{setTab(id);setVisibleCount(30);};
 return <div className="hub-workspace">
  <PageHeading label="DISCOVER / NEWS" title="Новини для тебе" subtitle="Цікаво — навчає стрічку й прибирає новину; Не цікаво — просто прибирає; Зберегти — до вибраного." action={<button className="button primary" disabled={busy} onClick={()=>void load()}><RefreshCw size={16}/>{busy?'Оновлення…':'Оновити стрічку'}</button>}/>
  <div className="hub-tool-row" style={{marginBottom:12}}><button className="hub-soft-button" disabled={busy} onClick={()=>void (async()=>{setBusy(true);try{const r=await window.lifehub.repairNewsImages();await refresh();report(`Перевірено фото: знайдено ${r.repaired} нових для ${r.total} статей. Якщо у видавця немає картинки, залишиться логотип.`);}catch(e){report(String(e));}finally{setBusy(false);}})()}><Sparkles size={16}/> Знайти фото для поточних новин</button></div>
  <div className="hub-news-controls"><div className="hub-tabs">{[['all','Для тебе'],['saved',`Збережене (${snapshot.newsSaved.length})`],...Object.entries(newsCat)].map(([id,name])=><button className={tab===id?'active':''} onClick={()=>changeTab(id)} key={id}>{name}</button>)}</div><select className="hub-mini-select" value={sort} onChange={e=>setSort(e.target.value as typeof sort)}><option value="forYou">За інтересами</option><option value="recent">Найновіші</option></select></div>
  <div className="hub-news-filter-note"><Heart size={14}/> Твій лайк впливає на майбутні рекомендації. Дизлайк не створює жодної доступної колекції прихованого. Збережені статті — окремо.</div>
  <div className="hub-source-note"><Bell size={15}/>{snapshot.news.fetchedAt?`Оновлено: ${new Date(snapshot.news.fetchedAt).toLocaleString('uk-UA')}`:'Стрічка ще не оновлювалася.'} · AI-банери створюються лише за твоїм підтвердженням, за окрему плату OpenAI. Завжди позначені як ілюстрації, не фото події.</div>
  <div className="hub-news-grid">{sorted.slice(0,visibleCount).map(a=>{
   const illustration=snapshot.newsIllustrations[a.id];const display:NewsEntry=illustration?{...a,imageUrl:illustration,imageCaption:'AI-ілюстрація — не фото події',imageCreditUrl:''}:a;
   return <article className="hub-surface hub-news-card" key={a.id}>
    <NewsVisual key={`${a.id}-${illustration?'ai':'original'}`} article={display}/><div className="hub-news-top"><span className="hub-chip">{newsCat[a.category]||a.category}</span><small>{a.source} · {new Date(a.publishedAt).toLocaleDateString('uk-UA')}</small></div>
    <h2>{translations[a.id]||a.title}</h2>
    <div className="hub-news-actions">{tab==='saved'?<button className="hub-soft-button" onClick={()=>void unsave(a.id)}>Прибрати зі збереженого</button>:<>
     <button disabled={!snapshot.hasKey||translating===a.id} className="hub-soft-button" onClick={()=>void translate(a,'uk')} title="Платний переклад">UA</button><button disabled={!snapshot.hasKey||translating===a.id} className="hub-soft-button" onClick={()=>void translate(a,'ru')} title="Платний переклад">RU</button>
     <button className="hub-soft-button" onClick={()=>void act(a.id,'interesting')}><Heart size={15}/> Цікаво</button>
     <button className="hub-soft-button is-danger" onClick={()=>void act(a.id,'not')}><HeartOff size={15}/> Не цікаво</button>
     <button className="hub-soft-button" onClick={()=>void act(a.id,'save')}><Save size={15}/> Зберегти</button>
     <button title="Додати справу" className="hub-icon-button" onClick={()=>onAddTask(nowDate(),'personal',`Прочитати: ${a.title.slice(0,80)}`)}><CalendarDays size={16}/></button>
    </>}
    {!illustration&&<button className="hub-soft-button" disabled={!snapshot.hasKey||Boolean(generating)} title="Згенерувати умовну ілюстрацію. Платний OpenAI Images API." onClick={()=>setImageConfirm(a.id)}><Sparkles size={14}/> AI-банер</button>}
    <button title="Відкрити джерело" className="hub-icon-button" onClick={()=>void window.lifehub.openLink(a.url).catch(e=>report(String(e)))}><ExternalLink size={16}/></button></div>
    {imageConfirm===a.id&&<div className="hub-news-image-consent"><strong>Створити банер до цієї новини?</strong><p>Запит платний, використовує OpenAI API й твій бюджет. Це **не справжнє фото події**. Максимум 3 банери на місяць.</p><div className="hub-tool-row"><button disabled={Boolean(generating)} onClick={()=>void illustrate(a.id)} className="button primary">{generating?'Генерую…':'Підтвердити генерацію'}</button><button className="hub-soft-button" onClick={()=>setImageConfirm(null)}>Скасувати</button></div></div>}
   </article>;
  })}
   {!sorted.length&&<section className="hub-surface"><Empty icon={<Search size={28}/>} title={tab==='saved'?'Немає збережених новин':'Немає новин у цій категорії'} body="Онови стрічку або обери іншу категорію."/></section>}
  </div>
  {sorted.length>visibleCount&&<div className="hub-news-paging"><button className="hub-soft-button" onClick={()=>setVisibleCount(n=>n+30)}>Показати ще · залишилося {sorted.length-visibleCount}</button></div>}
  <p className="hub-footnote">Збережені заголовки використовуються лише для твоїх інтересів. «Не цікаво» зберігає тільки технічний ID, щоб новина знову не з’явилася після оновлення.</p>
 </div>;
}

function MusicChartsPanel({snapshot,refresh,report}:Pick<WorkspaceActions,'snapshot'|'refresh'|'report'>){
 const [busy,setBusy]=useState(false),[freshOnly,setFreshOnly]=useState(false);
 async function reload(){setBusy(true);try{const x=await window.lifehub.refreshMusic();await refresh();report(Object.values(x.markets).some(a=>a.length)?'Музичні чарти оновлено':'Чарти недоступні: перевір інтернет або спробуй пізніше');}catch(e){report(String(e));}finally{setBusy(false);}}
 const music=snapshot.music;
 const threshold=addDays(nowDate(),-7);
 const sourceMarkets=music.markets||{};
 const countryLabel:Record<string,string>={us:'США',kz:'Казахстан',ua:'Україна',ru:'Росія'};
 const renderRows=(region:'us'|'regional')=>{
  const countries=region==='us'?['us']:['kz','ru','ua'];
  const combined=countries.flatMap(c=>(sourceMarkets[c]||[]).map(track=>({...track,market:c})));
  const freshAlbums=countries.flatMap(c=>(music.freshReleases?.[c]||[]).map(track=>({...track,market:c})));
  const filtered=freshOnly?[...combined.filter(t=>t.releaseDate&&t.releaseDate>=threshold&&t.releaseDate<=nowDate()),...freshAlbums.filter(t=>t.releaseDate&&t.releaseDate>=threshold&&t.releaseDate<=nowDate())]:combined;
  const seen=new Set<string>();
  const unique=filtered.filter(t=>{const key=(t.title+'|'+t.artist).toLowerCase();if(seen.has(key))return false;seen.add(key);return true;}).sort((a,b)=>a.rank-b.rank).slice(0,12);
  return <section className="hub-chart-column" key={region}><h3>{region==='us'?'🇺🇸 США':'🌍 СНД / регіон'}</h3><p className="muted">{region==='us'?'Apple Music · США':'Казахстан, Росія (якщо доступна), Україна — окремі рейтинги'}</p><div className="hub-chart-entries">{unique.map(t=><div key={t.market+'-'+t.id} className="hub-chart-entry"><span className="hub-chart-rank">{t.rank}</span>{t.artworkUrl?<img src={t.artworkUrl} loading="lazy" alt="Обкладинка треку" referrerPolicy="no-referrer" onError={e=>{e.currentTarget.style.display='none';}}/>:<div className="hub-chart-placeholder"><Music2 size={20}/></div>}<div className="hub-chart-info"><strong>{t.title}</strong><small>{t.artist} · {countryLabel[t.market]||t.market}</small>{t.releaseDate&&<small>{t.source==='new-album'?'З нового альбому · ':t.releaseDate>=threshold&&t.releaseDate<=nowDate()?'Новий реліз · ':''}{readable(t.releaseDate)}</small>}</div><button className="hub-soft-button" title="Пошук цієї пісні у Spotify (не гарантовано точний збіг)" onClick={()=>void window.lifehub.openLink(`https://open.spotify.com/search/${encodeURIComponent(t.title+' '+t.artist)}`).catch(e=>report(String(e)))}>Spotify <ArrowUpRight size={14}/></button><button className="hub-icon-button" title="Відкрити оригінальне джерело Apple Music" onClick={()=>void window.lifehub.openLink(t.url).catch(e=>report(String(e)))}><ExternalLink size={15}/></button></div>)}{!unique.length&&<p className="muted">{freshOnly?'Доступні джерела не підтвердили релізів за останні 7 днів. Список не заповнюється старими хітами.':'Немає даних із цього регіону. Онови чарти.'}</p>}</div></section>;
 };
 return <section className="hub-surface hub-music-charts"><div className="hub-section-head"><div><h2>Музичні тренди п’ятниці</h2><p>Чарти популярних треків із США та регіону. Для новинок використовуємо топ-100 пісень і треки з нещодавно випущених популярних альбомів.</p></div><button className="hub-soft-button" disabled={busy} onClick={()=>void reload()}><RefreshCw size={15}/>{busy?'Завантаження…':'Оновити чарти'}</button></div><div className="hub-tool-row"><button className={`hub-soft-button ${!freshOnly?'is-picked':''}`} onClick={()=>setFreshOnly(false)}>Популярні зараз</button><button className={`hub-soft-button ${freshOnly?'is-picked':''}`} onClick={()=>setFreshOnly(true)}>Вийшли за 7 днів</button></div><div className="hub-chart-grid">{renderRows('us')}{renderRows('regional')}</div><p className="hub-footnote">Джерело: {music.source||'Apple Music RSS'}. {music.fetchedAt?`Оновлено ${new Date(music.fetchedAt).toLocaleString('uk-UA')}.`:''} Це регіональні музичні чарти, не рейтинг TikTok та не доказ популярності в усіх країнах СНД. Для нових альбомів дата належить альбому, не обов’язково окремій пісні. Дані можуть оновлюватися із затримкою.{music.errors?.length?` Недоступні ринки: ${music.errors.join(', ')}.`:''}</p></section>;
}

export function MusicPage(props:WorkspaceActions){const {snapshot,refresh,report}=props,edit=useEditor(props);const items=snapshot.workspace.songs;const pending=items.filter(x=>x.status!=='added');const [onlyPending,setOnlyPending]=useState(true);const [collection,setCollection]=useState(snapshot.preferences.tiktokCollectionUrl||'');const [checking,setChecking]=useState(false);const [recognized,setRecognized]=useState<{source:string;found:boolean;title?:string;artist?:string;album?:string;spotifyUrl?:string;message:string}|null>(null);const [recognizing,setRecognizing]=useState(false);const [checkStatus,setCheckStatus]=useState<{status:string;message:string;title:string;author:string;videos?:{url:string;title:string;author:string;sound:string}[]}|null>(null);const nextFriday=addDays(nowDate(),(5-new Date().getDay()+7)%7);
 async function mark(song:WorkspaceItem){try{await window.lifehub.editWorkspace('songs',song.id,{status:song.status==='added'?'queued':'added'});await refresh();}catch(e){report(String(e));}}
 async function saveCollection(){try{await window.lifehub.setPreferences({tiktokCollectionUrl:collection} as Partial<import('./types').Preferences>);await refresh();report('Посилання на колекцію збережено');}catch(e){report(String(e));}}
 async function exportCsv(){try{const ok=await window.lifehub.exportSongs();if(ok)report('CSV створено');}catch(e){report(String(e));}}
 async function recognizeClip(source=''){
 setRecognizing(true);
 try{
  const {recordPlayingAudio}=await import('./recordAudio');
  const recorded=await recordPlayingAudio(source);
  const r=await window.lifehub.recognizeCapturedAudio(recorded);
  setRecognized({...r,source});
 }catch(e){report('Не вдалося розпізнати звук: '+(e instanceof Error?e.message:String(e))+'. Можна спробувати локальний аудіофайл.');}
 finally{setRecognizing(false);}
 }
 async function recognizeLocal(){setRecognizing(true);try{const r=await window.lifehub.recognizeAudio();if(r)setRecognized({...r,source:''});}catch(e){report(String(e));}finally{setRecognizing(false);}}
 async function addRecognized(){if(!recognized?.found)return;try{await window.lifehub.addWorkspace('songs',{title:recognized.title,artist:recognized.artist,url:recognized.source||recognized.spotifyUrl||'',note:'AudD: перевірено вручну',status:'queued',week:nextFriday});await refresh();report('Розпізнаний трек додано в музичну чергу');}catch(e){report(e instanceof Error?e.message:String(e));}}
 async function checkCollection(){setChecking(true);setCheckStatus(null);try{const result=await window.lifehub.checkTikTok(collection.trim());setCheckStatus(result);}catch(e){setCheckStatus({status:'error',message:'Помилка перевірки посилання: '+String(e),title:'',author:''});}finally{setChecking(false);}}
 return <div className="hub-workspace"><PageHeading label="LIFESTYLE / MUSIC" title="Музична п’ятниця" subtitle="Збирай пісні з TikTok та інших місць протягом тижня, а щоп’ятниці оновлюй плейлист." action={<button className="button primary" onClick={()=>edit.open('songs')}><Plus size={16}/> Додати трек</button>}/><div className="hub-music-hero"><div><div className="hub-kicker">NEXT PLAYLIST UPDATE</div><h2>П’ятниця · {readable(nextFriday)}</h2><p>Початок тижневої музичної сесії — 00:00. Сповіщення показується, якщо LifeHub працює в п’ятницю.</p></div><div className="hub-music-count"><Music2 size={27}/><strong>{pending.length}</strong><span>треків чекають</span></div></div><section className="hub-surface hub-collection"><div className="hub-section-head"><div><h2>Моя TikTok-колекція</h2><p>Для повної адреси колекції LifeHub спробує прочитати видимі відео через окреме вікно TikTok. Можливо, потрібно буде один раз увійти в TikTok у цьому вікні. Це не Shazam.</p></div></div><div className="hub-tool-row"><input type="url" placeholder="https://www.tiktok.com/..." value={collection} onChange={e=>{setCollection(e.target.value);setCheckStatus(null);}} /><button className="button outline" onClick={()=>void saveCollection()}>Зберегти</button><button className="hub-soft-button" disabled={checking||!collection.trim()} onClick={()=>void checkCollection()}><RefreshCw size={15}/>{checking?'Перевіряю…':'Перевірити зараз'}</button>{Boolean(snapshot.preferences.tiktokCollectionUrl)&&<button className="hub-soft-button" onClick={()=>void window.lifehub.openLink(snapshot.preferences.tiktokCollectionUrl).catch(e=>report(String(e)))}>Відкрити</button>}</div>{checkStatus&&<div className="hub-collection-status" role="status"><strong>{checkStatus.status==='video'?'Публічне відео розпізнано':checkStatus.status==='collection'?'Перевірка колекції':checkStatus.status==='short'?'Коротке посилання':checkStatus.status==='invalid'?'Некоректне посилання':checkStatus.status==='unavailable'?'Перевірка відео недоступна':'Перевірку завершено'}</strong><p>{checkStatus.message}</p>{checkStatus.title&&<small>Відео: {checkStatus.title}{checkStatus.author?` · ${checkStatus.author}`:''}</small>}{Boolean(checkStatus.videos?.length)&&<div className="hub-collected-videos">{checkStatus.videos?.map((video,index)=><div className="hub-collected-video" key={video.url}><span className="hub-clip-number">{index+1}</span><div><strong>{video.sound||video.title||'Відео без доступної назви звуку'}</strong><small>{video.author} · {video.sound?'Звук указаний TikTok':'Назва звуку не підтверджена'}</small></div><button className="hub-soft-button" onClick={()=>void window.lifehub.openLink(video.url).catch(e=>report(String(e)))}>TikTok <ExternalLink size={13}/></button><button className="hub-soft-button" disabled={recognizing||!snapshot.audDConnected} title="Записати 16 секунд звуку Windows під час відтворення TikTok і розпізнати через AudD" onClick={()=>void recognizeClip(video.url)}>{recognizing?'Запис звуку…':'Розпізнати звук'}</button>{(video.sound||video.title)&&<button className="hub-soft-button" title={video.sound?'Пошук за назвою звуку TikTok':'Пошук за підписом відео — збіг не підтверджено'} onClick={()=>void window.lifehub.openLink(`https://open.spotify.com/search/${encodeURIComponent(video.sound||video.title)}`).catch(e=>report(String(e)))}>Spotify</button>}</div>)}</div>}{recognized&&<div className="hub-collection-status"><strong>{recognized.found?`${recognized.artist} — ${recognized.title}`:'Трек не розпізнано'}</strong><p>{recognized.message}</p>{recognized.found&&<div className="hub-tool-row"><button className="button primary" onClick={()=>void addRecognized()}>Додати в музичну чергу</button>{recognized.spotifyUrl&&<button className="hub-soft-button" onClick={()=>void window.lifehub.openLink(recognized.spotifyUrl!)}>Spotify</button>}</div>}</div>}<div className="hub-tool-row"><button className="hub-soft-button" disabled={recognizing||!snapshot.audDConnected} onClick={()=>void recognizeLocal()}>Або вибрати аудіофайл</button></div><p className="hub-footnote">Розпізнавання з відтворення: після натискання LifeHub за твоєю згодою захоплює звук ПК протягом 16 секунд та відкриває TikTok. Відео повинно грати зі звуком, інші звуки на ПК краще вимкнути. У AudD надсилається тільки записаний аудіофрагмент. На Windows потрібен дозвіл на захоплення; якщо це не працює, вибери локальний аудіофайл.</p></div>}</section><MusicChartsPanel snapshot={snapshot} refresh={refresh} report={report}/><section className="hub-surface"><div className="hub-section-head"><div><h2>Моя черга треків</h2><p>Зараз немає автоматичного читання TikTok «Збережене» чи розпізнавання звуку лише за URL.</p></div><div className="hub-tool-row"><button className="hub-soft-button" onClick={()=>setOnlyPending(!onlyPending)}>{onlyPending?'Показати всі':'Тільки не додані'}</button><button className="hub-soft-button" onClick={()=>void exportCsv()}><FileText size={15}/> CSV</button></div></div><CardRows items={onlyPending?pending:items} render={i=><><div className="hub-song-cover"><Music2 size={19}/></div><div className="hub-record-body"><strong>{i.title}</strong><div className="hub-meta">{fieldText(i,'artist')||'Виконавець невідомий'} · {i.status==='added'?'У плейлисті':'Чекає'}</div>{Boolean(i.note)&&<p className="hub-record-detail">{fieldText(i,'note')}</p>}</div><div className="hub-song-actions">{Boolean(i.url)&&<button className="hub-icon-button" onClick={()=>void window.lifehub.openLink(fieldText(i,'url')).catch(e=>report(String(e)))} title="Відкрити TikTok"><ExternalLink size={15}/></button>}<button className="hub-soft-button" onClick={()=>void mark(i)}>{i.status==='added'?'Повернути':'Додано ✓'}</button></div><Actions onEdit={()=>edit.open('songs',i)} onRemove={()=>void edit.remove('songs',i.id)}/></>}/>{!(onlyPending?pending:items).length&&<Empty icon={<Music2 size={27}/>} title="Твоя музична добірка ще порожня" body="Додай пісню або TikTok-посилання, щоб не загубити знахідку до п’ятниці."/>}</section>{edit.editorNode}</div>;
}

export function WorkspaceSettings({snapshot,refresh,report}:WorkspaceActions){const p=snapshot.preferences;const [accent,setAccent]=useState(p.accent),[density,setDensity]=useState(p.density),[language,setLanguage]=useState(p.language),[auto,setAuto]=useState(p.newsAutoRefresh),[friday,setFriday]=useState(p.fridayReminder),[cats,setCats]=useState<string[]>(p.newsCategories),[nickname,setNickname]=useState(p.nickname),[avatarData,setAvatarData]=useState(p.avatarData);
 async function chooseAvatar(event:ChangeEvent<HTMLInputElement>){const file=event.target.files?.[0];if(!file)return;
 if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>850000){report('Потрібне фото PNG/JPEG/WebP розміром до 850 КБ');return;}
 const reader=new FileReader();reader.onload=()=>{if(typeof reader.result==='string')setAvatarData(reader.result);};reader.onerror=()=>report('Не вдалося відкрити фото');reader.readAsDataURL(file);
 }
 async function apply(){try{await window.lifehub.setPreferences({nickname,avatarData,accent,density,language,newsAutoRefresh:auto,fridayReminder:friday,newsCategories:cats});await refresh();report('Оформлення та стрічку збережено');}catch(e){report(String(e));}}
 return <section className="hub-surface hub-personalization"><div className="hub-section-head"><div><h2>Оформлення й персоналізація</h2><p>Змінюй стиль LifeHub без оновлення програми.</p></div></div><div className="hub-settings-row"><div><strong>Мій профіль</strong><p>Ім’я та фото зберігаються локально на комп’ютері</p></div><div className="hub-profile-avatar"><div className="avatar hub-avatar-preview">{avatarData?<img src={avatarData} alt="Аватар"/>:'LH'}</div><input type="text" maxLength={40} placeholder="Твоє ім’я" value={nickname} onChange={e=>setNickname(e.target.value)}/><label className="hub-upload-avatar">Фото <input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>void chooseAvatar(e)}/></label>{avatarData&&<button className="hub-soft-button" onClick={()=>setAvatarData('')}>Прибрати</button>}</div></div><div className="hub-settings-row"><div><strong>Акцентний колір</strong><p>Спокійний Spotify-подібний стиль без надмірних градієнтів</p></div><div className="hub-color-choice">{(['green','blue','violet','orange'] as const).map(c=><button key={c} title={c} aria-label={`Колір ${c}`} className={`${c} ${accent===c?'active':''}`} onClick={()=>setAccent(c)}/>)}</div></div><div className="hub-settings-row"><div><strong>Щільність інтерфейсу</strong></div><select value={density} onChange={e=>setDensity(e.target.value as typeof density)}><option value="comfortable">Комфортна</option><option value="compact">Компактна</option></select></div><div className="hub-settings-row"><div><strong>Мова</strong><p>Англійський переклад основної навігації (бета)</p></div><select value={language} onChange={e=>setLanguage(e.target.value as typeof language)}><option value="uk">Українська</option><option value="en">English (beta)</option></select></div><div className="hub-settings-row"><div><strong>Автооновлення новин</strong><p>Раз на добу, коли LifeHub запущений, без витрат OpenAI API</p></div><input type="checkbox" checked={auto} onChange={e=>setAuto(e.target.checked)}/></div><div className="hub-settings-row"><div><strong>Музична п’ятниця</strong><p>Раз на п’ятницю, коли LifeHub працює</p></div><input type="checkbox" checked={friday} onChange={e=>setFriday(e.target.checked)}/></div><div className="hub-settings-row hub-settings-cats"><div><strong>Джерела для стрічки</strong><p>Новини збираються з публічних RSS, а не платного AI.</p></div><div className="hub-filter-pills">{Object.entries(newsCat).map(([c,name])=><label key={c}><input type="checkbox" checked={cats.includes(c)} onChange={e=>setCats(old=>e.target.checked?[...old,c]:old.filter(x=>x!==c))}/>{name}</label>)}</div></div><button className="button primary" onClick={()=>void apply()}><Save size={16}/> Зберегти персоналізацію</button></section>;
}
